-- Frame offsets must be nonnegative 32-bit integers; the largest accepted one reaches past any partition.
SELECT number, sum(number) OVER (ORDER BY number ROWS BETWEEN 2147483646 PRECEDING AND 2147483646 FOLLOWING) FROM numbers(3);
SELECT number, sum(number) OVER (ORDER BY number RANGE BETWEEN 2147483646 PRECEDING AND 2147483646 FOLLOWING) FROM numbers(3);
SELECT number, sum(number) OVER (ORDER BY number GROUPS BETWEEN 2147483646 PRECEDING AND 2147483646 FOLLOWING) FROM numbers(3);

SELECT sum(number) OVER (ORDER BY number ROWS BETWEEN 2147483647 PRECEDING AND CURRENT ROW) FROM numbers(3); -- { serverError BAD_ARGUMENTS }
SELECT sum(number) OVER (ORDER BY number ROWS BETWEEN CURRENT ROW AND 2147483647 FOLLOWING) FROM numbers(3); -- { serverError BAD_ARGUMENTS }
SELECT sum(number) OVER (ORDER BY number ROWS BETWEEN 9223372036854775808 PRECEDING AND CURRENT ROW) FROM numbers(3); -- { serverError BAD_ARGUMENTS }
SELECT sum(number) OVER (ORDER BY number ROWS BETWEEN CURRENT ROW AND 18446744073709551615 FOLLOWING) FROM numbers(3); -- { serverError BAD_ARGUMENTS }
SELECT sum(number) OVER (ORDER BY number RANGE BETWEEN 18446744073709551615 PRECEDING AND CURRENT ROW) FROM numbers(3); -- { serverError BAD_ARGUMENTS }
SELECT sum(number) OVER (ORDER BY number GROUPS BETWEEN 9223372036854775808 PRECEDING AND CURRENT ROW) FROM numbers(3); -- { serverError BAD_ARGUMENTS }
